import React, { useState } from 'react';
import axios from 'axios';

const TestCaseGenerator = () => {
    const [requirement, setRequirement] = useState('');
    const [testCases, setTestCases] = useState('');
    const [loading, setLoading] = useState(false);

    const generateTestCases = async () => {
        setLoading(true);
        setTestCases('');

        try {
            const response = await axios.post('http://localhost:5000/api/generate-test-cases', {
                requirement_text: requirement
            });
            setTestCases(response.data.test_cases);
        } catch (error) {
            console.error('Error generating test cases:', error);
            setTestCases('Failed to generate test cases.');
        }

        setLoading(false);
    };

    return (
        <div style={styles.container}>
            <h2>Test Case Generator</h2>
            <textarea
                rows="6"
                cols="50"
                placeholder="Enter requirement document here..."
                value={requirement}
                onChange={(e) => setRequirement(e.target.value)}
                disabled={loading}
                style={styles.textarea}
            />
            <br />
            <button onClick={generateTestCases} disabled={loading} style={styles.button}>
                {loading ? 'Generating...' : 'Generate Test Cases'}
            </button>
            <h3>Generated Test Cases:</h3>

            {loading ? (
                <div style={styles.loaderContainer}>
                    <div className="spinner"></div>
                    <p>Generating test cases...</p>
                </div>
            ) : (
                <pre style={styles.output}>{testCases}</pre>
            )}

            {/* CSS for Spinner */}
            <style>
                {`
                .spinner {
                    width: 40px;
                    height: 40px;
                    border: 4px solid rgba(0, 0, 0, 0.1);
                    border-left-color: #3498db;
                    border-radius: 50%;
                    animation: spin 1s linear infinite;
                }

                @keyframes spin {
                    0% { transform: rotate(0deg); }
                    100% { transform: rotate(360deg); }
                }
                `}
            </style>
        </div>
    );
};

// Basic Styles
const styles = {
    container: {
        textAlign: 'center',
        fontFamily: 'Arial, sans-serif',
        padding: '20px',
    },
    textarea: {
        width: '80%',
        padding: '10px',
        fontSize: '16px',
    },
    button: {
        marginTop: '10px',
        padding: '10px 20px',
        fontSize: '16px',
        cursor: 'pointer',
    },
    loaderContainer: {
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        marginTop: '20px',
    },
    output: {
        backgroundColor: '#f4f4f4',
        padding: '10px',
        borderRadius: '5px',
        textAlign: 'left',
        whiteSpace: 'pre-wrap',
    },
};

export default TestCaseGenerator;
